// ============================================================
// TRANSFORM SECTION
// ============================================================
function TransformSection({ t }) {
  const [files, setFiles] = useState([]);
  const [formData, setFormData] = useState({ name:"", phone:"", vision:"" });
  const [submitted, setSubmitted] = useState(false);
  const fileRef = useRef();

  const handleFiles = (e) => {
    const newFiles = Array.from(e.target.files).slice(0, 5 - files.length);
    setFiles(prev => [...prev, ...newFiles].slice(0, 5));
  };

  const handleSubmit = () => {
    if(!formData.name || !formData.phone) return;
    // In production this would POST to backend
    const existing = JSON.parse(window.sessionStorage?.getItem?.("dg_transforms") || "[]");
    existing.push({ ...formData, filesCount: files.length, date: new Date().toISOString(), id: Date.now() });
    try { window.sessionStorage.setItem("dg_transforms", JSON.stringify(existing)); } catch(e) {}
    setSubmitted(true);
    setTimeout(() => { setSubmitted(false); setFormData({name:"",phone:"",vision:""}); setFiles([]); }, 3000);
  };

  return (
    <section className="section sec-dark" id="transform">
      <div className="sec-header">
        <span className="sec-label">{t.transform.label}</span>
        <h2 className="sec-title" style={{color:"#F5F0EB"}}>{t.transform.title1} <em>{t.transform.titleEm}</em></h2>
        <p className="sec-sub" style={{color:"rgba(245,240,235,0.6)"}}>{t.transform.subtitle}</p>
      </div>
      <div className="transform-grid">
        <div className="transform-form">
          {submitted ? (
            <div className="success-msg">
              <div style={{fontSize:"48px",marginBottom:"16px"}}>✅</div>
              <h3>Faleminderit!</h3>
              <p>Kërkesa juaj u dërgua me sukses. Do t'ju kontaktojmë brenda 24 orëve.</p>
            </div>
          ) : (
            <>
              <div className="fg"><label>{t.transform.name}</label><input value={formData.name} onChange={e => setFormData({...formData, name:e.target.value})} placeholder="..." /></div>
              <div className="fg"><label>{t.transform.phone}</label><input value={formData.phone} onChange={e => setFormData({...formData, phone:e.target.value})} placeholder="+355 6X XXX XXXX" /></div>
              <div className="fg"><label>{t.transform.vision}</label><textarea value={formData.vision} onChange={e => setFormData({...formData, vision:e.target.value})} placeholder="..." rows={4} /></div>
              <div className="upload-zone" onClick={() => fileRef.current?.click()}>
                <div style={{fontSize:"32px",marginBottom:"8px"}}>📷</div>
                <p>{t.transform.upload}</p>
                <span>{t.transform.uploadHint}</span>
                <input ref={fileRef} type="file" multiple accept="image/*" onChange={handleFiles} style={{display:"none"}} />
              </div>
              {files.length > 0 && (
                <div className="file-previews">
                  {files.map((f,i) => (
                    <div key={i} className="file-preview">
                      <img src={URL.createObjectURL(f)} alt="" />
                      <button onClick={(e) => { e.stopPropagation(); setFiles(files.filter((_,j)=>j!==i)); }}>×</button>
                    </div>
                  ))}
                </div>
              )}
              <button className="btn-gold" style={{width:"100%",justifyContent:"center"}} onClick={handleSubmit}>{t.transform.send} →</button>
            </>
          )}
        </div>
        <div className="transform-visual">
          <div className="tv-img"><img src={IMAGES.show5} alt="Before" /></div>
          <div className="tv-label">
            <h3>{t.transform.beforeAfter}</h3>
            <p>{t.transform.baDesc}</p>
          </div>
          <div className="tv-img"><img src={IMAGES.show8} alt="After" /></div>
        </div>
      </div>
    </section>
  );
}

// ============================================================
// SOLAR SECTION
// ============================================================
function SolarSection({ t }) {
  const [bill, setBill] = useState("");
  const [currency, setCurrency] = useState("ALL");
  const [results, setResults] = useState(null);

  const calculate = () => {
    const b = parseFloat(bill);
    if(!b || b <= 0) return;
    const rate = currency === "EUR" ? 1 : 0.0088;
    const billEur = b * rate;
    const annual = billEur * 12;
    const savePct = 0.75;
    const annualSave = annual * savePct;
    const kwhPrice = 0.08;
    const annualKwh = annual / kwhPrice;
    const kwhPanel = 500;
    const panels = Math.ceil(annualKwh * savePct / kwhPanel);
    const cost = panels * 250;
    const payback = (cost / annualSave).toFixed(1);
    const sym = currency === "EUR" ? "€" : "L";
    const savings = currency === "EUR" ? annualSave.toFixed(0) : (annualSave / rate).toFixed(0);
    setResults({ savings: `${sym} ${parseInt(savings).toLocaleString()}`, kwh: parseInt(annualKwh * savePct).toLocaleString(), panels, payback });
  };

  return (
    <section className="section sec-solar" id="solar">
      <div className="sec-header">
        <span className="sec-label">{t.solar.label}</span>
        <h2 className="sec-title" style={{color:"#F5F0EB"}}>{t.solar.title1} <em>{t.solar.titleEm}</em></h2>
      </div>
      <div className="solar-grid">
        <div className="solar-info">
          <p>{t.solar.desc}</p>
          <div className="solar-features">
            {[{i:"🏠",t:t.solar.f1,d:t.solar.f1d},{i:"🏢",t:t.solar.f2,d:t.solar.f2d},{i:"🌾",t:t.solar.f3,d:t.solar.f3d},{i:"🔧",t:t.solar.f4,d:t.solar.f4d}].map((f,idx) => (
              <div className="sf-card" key={idx}><span className="sf-icon">{f.i}</span><h4>{f.t}</h4><p>{f.d}</p></div>
            ))}
          </div>
          <a href="#contact" className="btn-gold" style={{alignSelf:"flex-start",marginTop:"20px"}} onClick={e => { e.preventDefault(); document.getElementById("contact")?.scrollIntoView({behavior:"smooth"}); }}>{t.solar.cta} →</a>
        </div>
        <div className="calc-card">
          <h3>☀️ {t.solar.calcTitle}</h3>
          <p className="calc-sub">{t.solar.calcSub}</p>
          <div className="fg"><label>{t.solar.billLabel}</label><input type="number" value={bill} onChange={e => setBill(e.target.value)} placeholder="8000" /></div>
          <div className="fg"><label>{t.solar.currency}</label>
            <select value={currency} onChange={e => setCurrency(e.target.value)}>
              <option value="ALL">Lekë (ALL)</option>
              <option value="EUR">Euro (EUR)</option>
            </select>
          </div>
          <button className="btn-gold" style={{width:"100%",justifyContent:"center",marginTop:"12px"}} onClick={calculate}>{t.solar.calculate}</button>
          {results && (
            <div className="calc-results">
              <div className="cr"><span className="cr-val">{results.savings}</span><span className="cr-lbl">{t.solar.annualSave}</span></div>
              <div className="cr"><span className="cr-val">{results.kwh}</span><span className="cr-lbl">{t.solar.kwh}</span></div>
              <div className="cr"><span className="cr-val">{results.panels}</span><span className="cr-lbl">{t.solar.panels}</span></div>
              <div className="cr"><span className="cr-val">{results.payback}</span><span className="cr-lbl">{t.solar.payback}</span></div>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

