function ContactSection({ t }) {
  const [form, setForm] = useState({ name:"", email:"", phone:"", message:"" });
  const [sent, setSent] = useState(false);

  const handleSend = () => {
    if(!form.name || !form.phone) return;
    const existing = JSON.parse(window.sessionStorage?.getItem?.("dg_quotes") || "[]");
    existing.push({ ...form, date: new Date().toISOString(), id: Date.now(), type:"contact" });
    try { window.sessionStorage.setItem("dg_quotes", JSON.stringify(existing)); } catch(e) {}
    setSent(true);
    setTimeout(() => { setSent(false); setForm({name:"",email:"",phone:"",message:""}); }, 3000);
  };

  return (
    <section className="section sec-alt" id="contact">
      <div className="sec-header">
        <span className="sec-label">{t.contact.label}</span>
        <h2 className="sec-title">{t.contact.title1} <em>{t.contact.titleEm}</em></h2>
        <p className="sec-sub">{t.contact.subtitle}</p>
      </div>
      <div className="contact-grid">
        <div className="contact-form">
          {sent ? (
            <div className="success-msg" style={{background:"rgba(196,162,101,0.08)",borderRadius:"20px",padding:"48px"}}>
              <div style={{fontSize:"48px",marginBottom:"16px"}}>✅</div>
              <h3>Faleminderit!</h3>
              <p>Mesazhi juaj u dërgua.</p>
            </div>
          ) : (
            <>
              <div className="form-row">
                <div className="fg"><label>{t.contact.name}</label><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} /></div>
                <div className="fg"><label>{t.contact.email}</label><input value={form.email} onChange={e=>setForm({...form,email:e.target.value})} type="email" /></div>
              </div>
              <div className="fg"><label>{t.contact.phone}</label><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} /></div>
              <div className="fg"><label>{t.contact.message}</label><textarea value={form.message} onChange={e=>setForm({...form,message:e.target.value})} rows={5} /></div>
              <button className="btn-gold" style={{width:"100%",justifyContent:"center"}} onClick={handleSend}>{t.contact.send} →</button>
            </>
          )}
        </div>
        <div className="contact-info">
          <h3>{t.contact.info}</h3>
          <div className="ci-item"><span>📍</span><div><strong>Showroom</strong><br/>{t.contact.address}</div></div>
          <div className="ci-item"><span>📞</span><div><strong>{t.contact.phone}</strong><br/>+355 68 203 3446</div></div>
          <div className="ci-item"><span>🕐</span><div><strong>{t.contact.hours || "Orari"}</strong><br/>{t.contact.hours}</div></div>
          <div className="ci-item"><span>💬</span><div><strong>WhatsApp</strong><br/><a href="https://wa.me/355682033446" target="_blank" rel="noreferrer" style={{color:"#C4A265"}}>+355 68 203 3446</a></div></div>
          <div className="contact-map">
            <iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2998.5!2d20.0!3d40.98!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zNDDCsDU5JzE2LjgiTiAyMMKwMDAnMDAuMCJF!5e0!3m2!1sen!2s!4v1" width="100%" height="200" style={{border:0,borderRadius:"16px"}} allowFullScreen loading="lazy" />
          </div>
        </div>
      </div>
    </section>
  );
}

// ============================================================
// ADMIN PANEL
// ============================================================
function AdminPanel({ auth, setAuth, setPage, dark }) {
  const [loginForm, setLoginForm] = useState({ email:"", password:"" });
  const [loginError, setLoginError] = useState("");
  const [activeTab, setActiveTab] = useState("dashboard");

  // Data from sessionStorage
  const [quotes, setQuotes] = useState([]);
  const [transforms, setTransforms] = useState([]);
  const [products, setProducts] = useState([]);
  const [blogs, setBlogs] = useState([]);
  const [projects, setProjects] = useState([]);

  useEffect(() => {
    try {
      setQuotes(JSON.parse(window.sessionStorage?.getItem?.("dg_quotes") || "[]"));
      setTransforms(JSON.parse(window.sessionStorage?.getItem?.("dg_transforms") || "[]"));
      setProducts(JSON.parse(window.sessionStorage?.getItem?.("dg_products") || "[]"));
      setBlogs(JSON.parse(window.sessionStorage?.getItem?.("dg_blogs") || "[]"));
      setProjects(JSON.parse(window.sessionStorage?.getItem?.("dg_projects") || "[]"));
    } catch(e) {}
  }, [activeTab]);

  const handleLogin = () => {
    const user = ADMIN_USERS.find(u => u.email === loginForm.email && u.password === loginForm.password);
    if(user) { setAuth(user); setLoginError(""); }
    else setLoginError("Email ose fjalëkalim i gabuar.");
  };

  if(!auth) {
    return (
      <div className="admin-login-wrap">
        <style>{globalCSS}</style>
        <div className="admin-login-card">
          <img src={IMAGES.logo} alt="Dervishi Group" style={{height:"40px",marginBottom:"32px",filter:dark?"brightness(10)":"none"}} />
          <h2>Admin Panel</h2>
          <p style={{color:"#9B958E",marginBottom:"32px"}}>Identifikohuni për të hyrë në panelin e administrimit.</p>
          {loginError && <div className="login-error">{loginError}</div>}
          <div className="fg"><label>Email</label><input value={loginForm.email} onChange={e=>setLoginForm({...loginForm,email:e.target.value})} type="email" placeholder="admin@dervishigroup.com" /></div>
          <div className="fg" style={{marginTop:"12px"}}><label>Fjalëkalimi</label><input value={loginForm.password} onChange={e=>setLoginForm({...loginForm,password:e.target.value})} type="password" placeholder="••••••••" onKeyDown={e => e.key==="Enter"&&handleLogin()} /></div>
          <button className="btn-gold" style={{width:"100%",justifyContent:"center",marginTop:"24px"}} onClick={handleLogin}>Hyr →</button>
          <button className="btn-outline" style={{width:"100%",justifyContent:"center",marginTop:"12px"}} onClick={() => setPage("home")}>← Kthehu në Faqe</button>
        </div>
      </div>
    );
  }

  const saveProducts = (p) => { setProducts(p); try{window.sessionStorage.setItem("dg_products",JSON.stringify(p));}catch(e){} };
  const saveBlogs = (b) => { setBlogs(b); try{window.sessionStorage.setItem("dg_blogs",JSON.stringify(b));}catch(e){} };
  const saveProjects = (p) => { setProjects(p); try{window.sessionStorage.setItem("dg_projects",JSON.stringify(p));}catch(e){} };

  return (
    <div className="admin-wrap">
      <style>{globalCSS}</style>
      <div className="admin-sidebar">
        <div className="admin-brand">
          <img src={IMAGES.logo} alt="DG" style={{height:"32px",filter:"brightness(10)"}} />
          <span>Admin</span>
        </div>
        <nav className="admin-nav">
          {[
            {id:"dashboard",icon:"📊",label:"Dashboard"},
            {id:"quotes",icon:"📩",label:"Oferta / Quote"},
            {id:"transforms",icon:"📸",label:"Transformime"},
            {id:"products",icon:"🛒",label:"Produkte"},
            {id:"blogs",icon:"📝",label:"Blog"},
            {id:"projects",icon:"🏗️",label:"Portfolio"},
            {id:"solar",icon:"☀️",label:"Solar Config"},
          ].map(tab => (
            <button key={tab.id} className={`admin-tab ${activeTab===tab.id?"active":""}`} onClick={() => setActiveTab(tab.id)}>
              <span>{tab.icon}</span>{tab.label}
            </button>
          ))}
        </nav>
        <div className="admin-user">
          <div className="admin-avatar">U</div>
          <div><strong>{auth.email.split("@")[0]}</strong><br/><small>{auth.role}</small></div>
        </div>
        <button className="admin-logout" onClick={() => { setAuth(null); setPage("home"); }}>↩ Dil / Kthehu</button>
      </div>
      <div className="admin-main">
        <div className="admin-topbar">
          <h1>{activeTab === "dashboard" ? "Dashboard" : activeTab === "quotes" ? "Kërkesat për Ofertë" : activeTab === "transforms" ? "Kërkesat për Transformim" : activeTab === "products" ? "Menaxho Produktet" : activeTab === "blogs" ? "Menaxho Blog" : activeTab === "projects" ? "Portfolio / Projekte" : "Solar Konfigurim"}</h1>
          <span className="admin-date">{new Date().toLocaleDateString("sq-AL",{weekday:"long",year:"numeric",month:"long",day:"numeric"})}</span>
        </div>
        <div className="admin-content">
          {activeTab === "dashboard" && (
            <div className="dash-grid">
              <div className="dash-card"><div className="dc-icon">📩</div><div className="dc-num">{quotes.length}</div><div className="dc-label">Kërkesa Oferte</div></div>
              <div className="dash-card"><div className="dc-icon">📸</div><div className="dc-num">{transforms.length}</div><div className="dc-label">Kërkesa Transformimi</div></div>
              <div className="dash-card"><div className="dc-icon">🛒</div><div className="dc-num">{products.length}</div><div className="dc-label">Produkte</div></div>
              <div className="dash-card"><div className="dc-icon">📝</div><div className="dc-num">{blogs.length}</div><div className="dc-label">Blog Posts</div></div>
              <div className="dash-card"><div className="dc-icon">🏗️</div><div className="dc-num">{projects.length}</div><div className="dc-label">Projekte</div></div>
              <div className="dash-card"><div className="dc-icon">☀️</div><div className="dc-num">—</div><div className="dc-label">Solar Config</div></div>
            </div>
          )}
          {activeTab === "quotes" && <AdminTable data={quotes} columns={["date","name","email","phone","message","type"]} />}
          {activeTab === "transforms" && <AdminTable data={transforms} columns={["date","name","phone","vision","filesCount"]} />}
          {activeTab === "products" && <AdminCRUD items={products} setItems={saveProducts} fields={["name","category","description"]} label="Produkt" />}
          {activeTab === "blogs" && <AdminCRUD items={blogs} setItems={saveBlogs} fields={["title","category","content"]} label="Blog Post" />}
          {activeTab === "projects" && <AdminCRUD items={projects} setItems={saveProjects} fields={["title","description","duration"]} label="Projekt" />}
          {activeTab === "solar" && (
            <div className="admin-solar-config">
              <p style={{color:"#9B958E",marginBottom:"24px"}}>Konfiguroni parametrat e llogaritësit solar.</p>
              <div className="form-row">
                <div className="fg"><label>Çmimi kWh (EUR)</label><input defaultValue="0.08" /></div>
                <div className="fg"><label>kWh/panel/vit</label><input defaultValue="500" /></div>
              </div>
              <div className="form-row">
                <div className="fg"><label>Kosto/panel (EUR)</label><input defaultValue="250" /></div>
                <div className="fg"><label>% Kursimi</label><input defaultValue="75" /></div>
              </div>
              <button className="btn-gold" style={{marginTop:"16px"}}>Ruaj Ndryshimet</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function AdminTable({ data, columns }) {
  if(!data.length) return <div className="admin-empty">Asnjë rekord ende.</div>;
  return (
    <div className="admin-table-wrap">
      <table className="admin-table">
        <thead><tr>{columns.map(c => <th key={c}>{c}</th>)}</tr></thead>
        <tbody>{data.map((row,i) => (
          <tr key={i}>{columns.map(c => <td key={c}>{c==="date"?new Date(row[c]).toLocaleDateString("sq-AL"):row[c]||"—"}</td>)}</tr>
        ))}</tbody>
      </table>
    </div>
  );
}

function AdminCRUD({ items, setItems, fields, label }) {
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState({});
  const [editing, setEditing] = useState(null);

  const handleSave = () => {
    if(editing !== null) {
      const updated = [...items];
      updated[editing] = { ...updated[editing], ...form };
      setItems(updated);
    } else {
      setItems([...items, { ...form, id: Date.now(), date: new Date().toISOString() }]);
    }
    setForm({}); setAdding(false); setEditing(null);
  };

  const handleDelete = (i) => { setItems(items.filter((_,j)=>j!==i)); };
  const handleEdit = (i) => { setForm(items[i]); setEditing(i); setAdding(true); };

  return (
    <div>
      <button className="btn-gold" style={{marginBottom:"24px"}} onClick={() => { setAdding(true); setForm({}); setEditing(null); }}>+ Shto {label}</button>
      {adding && (
        <div className="admin-form-card">
          {fields.map(f => (
            <div className="fg" key={f}>
              <label>{f}</label>
              {f === "content" || f === "description" ? (
                <textarea value={form[f]||""} onChange={e => setForm({...form,[f]:e.target.value})} rows={4} />
              ) : (
                <input value={form[f]||""} onChange={e => setForm({...form,[f]:e.target.value})} />
              )}
            </div>
          ))}
          <div style={{display:"flex",gap:"12px",marginTop:"16px"}}>
            <button className="btn-gold" onClick={handleSave}>💾 Ruaj</button>
            <button className="btn-outline" onClick={() => { setAdding(false); setEditing(null); }}>Anulo</button>
          </div>
        </div>
      )}
      {!items.length && !adding && <div className="admin-empty">Asnjë {label.toLowerCase()} ende. Klikoni "+ Shto" për të filluar.</div>}
      {items.length > 0 && (
        <div className="admin-cards">
          {items.map((item,i) => (
            <div className="admin-item-card" key={i}>
              <div className="aic-header">
                <strong>{item[fields[0]] || `${label} ${i+1}`}</strong>
                <div style={{display:"flex",gap:"8px"}}>
                  <button className="aic-btn" onClick={() => handleEdit(i)}>✏️</button>
                  <button className="aic-btn" onClick={() => handleDelete(i)}>🗑️</button>
                </div>
              </div>
              {fields.slice(1).map(f => item[f] ? <p key={f} className="aic-detail"><small>{f}:</small> {item[f]}</p> : null)}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================
// GLOBAL CSS
// ============================================================
const globalCSS = `
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;0,700;1,300;1,400&family=Outfit:wght@200;300;400;500;600;700&display=swap');

:root {
  --bg: #F5F0EB; --bg2: #EDE8E3; --gray: #D4CFC9; --mgray: #9B958E;
  --dark: #3A3631; --black: #1E1C19; --gold: #C4A265; --goldL: #D4B87A;
  --ff: 'Outfit',sans-serif; --fd: 'Cormorant Garamond',Georgia,serif;
  --r: 16px; --rl: 24px;
}
[data-theme="dark"] {
  --bg: #1A1816; --bg2: #222019; --gray: #3A3631; --mgray: #7A746D;
  --dark: #E8E3DD; --black: #F5F0EB;
}
* { margin:0; padding:0; box-sizing:border-box; }
html { scroll-behavior:smooth; }
body, .app { font-family:var(--ff); background:var(--bg); color:var(--dark); overflow-x:hidden; transition:background .4s,color .4s; }

/* NAVBAR */
.navbar { position:fixed; top:0; left:0; right:0; z-index:1000; display:flex; align-items:center; justify-content:space-between; padding:18px 48px; background:rgba(245,240,235,0.82); backdrop-filter:blur(24px); -webkit-backdrop-filter:blur(24px); border-bottom:1px solid rgba(196,162,101,0.1); transition:all .35s; }
[data-theme="dark"] .navbar { background:rgba(26,24,22,0.88); }
.navbar.scrolled { padding:12px 48px; box-shadow:0 4px 32px rgba(0,0,0,0.06); }
.nav-logo { height:40px; transition:height .3s; }
.navbar.scrolled .nav-logo { height:32px; }
.nav-links { display:flex; gap:28px; align-items:center; }
.nav-links a { font-size:12px; font-weight:500; color:var(--dark); text-decoration:none; letter-spacing:1.8px; text-transform:uppercase; position:relative; transition:color .3s; }
.nav-links a::after { content:''; position:absolute; bottom:-4px; left:0; width:0; height:1.5px; background:var(--gold); transition:width .3s; }
.nav-links a:hover::after { width:100%; }
.nav-links a:hover { color:var(--gold); }
.nav-right { display:flex; gap:12px; align-items:center; }
.lang-sel { background:transparent; border:1px solid var(--gray); border-radius:8px; padding:6px 10px; font-family:var(--ff); font-size:11px; color:var(--dark); cursor:pointer; letter-spacing:1px; }
.lang-sel option { background:var(--bg); }
.theme-btn { background:none; border:1px solid var(--gray); border-radius:50%; width:36px; height:36px; cursor:pointer; display:flex; align-items:center; justify-content:center; font-size:14px; transition:all .3s; }
.theme-btn:hover { border-color:var(--gold); }
.nav-cta { background:var(--gold); color:#fff; padding:10px 22px; border-radius:50px; font-size:11px; font-weight:600; text-decoration:none; letter-spacing:1.5px; text-transform:uppercase; transition:all .3s; }
.nav-cta:hover { background:var(--goldL); }
.hamburger { display:none; background:none; border:none; flex-direction:column; gap:5px; cursor:pointer; padding:4px; }
.hamburger span { display:block; width:22px; height:2px; background:var(--dark); transition:all .3s; }

/* HERO */
.hero { min-height:100vh; display:flex; align-items:center; padding:120px 48px 80px; gap:48px; }
.hero-content { flex:1; max-width:540px; }
.hero-badge { display:inline-flex; align-items:center; gap:8px; background:rgba(196,162,101,0.1); border:1px solid rgba(196,162,101,0.2); padding:8px 20px; border-radius:50px; font-size:11px; font-weight:600; letter-spacing:2.5px; text-transform:uppercase; color:var(--gold); margin-bottom:28px; animation:fadeUp .8s ease both; }
.hero-badge::before { content:''; width:6px; height:6px; background:var(--gold); border-radius:50%; }
.hero-title { font-family:var(--fd); font-size:clamp(36px,5vw,64px); font-weight:300; line-height:1.1; color:var(--black); margin-bottom:20px; animation:fadeUp .8s ease .15s both; }
.hero-title em { font-style:italic; color:var(--gold); font-weight:400; }
.hero-sub { font-size:16px; font-weight:300; line-height:1.7; color:var(--mgray); margin-bottom:36px; max-width:420px; animation:fadeUp .8s ease .3s both; }
.hero-actions { display:flex; gap:14px; flex-wrap:wrap; animation:fadeUp .8s ease .45s both; }
.btn-gold { background:var(--gold); color:#fff; padding:14px 32px; border-radius:50px; font-family:var(--ff); font-size:12px; font-weight:600; letter-spacing:1.5px; text-transform:uppercase; text-decoration:none; border:none; cursor:pointer; transition:all .3s; display:inline-flex; align-items:center; gap:8px; }
.btn-gold:hover { background:var(--goldL); transform:translateY(-2px); box-shadow:0 8px 28px rgba(196,162,101,0.3); }
.btn-outline { background:transparent; border:1.5px solid var(--gray); color:var(--dark); padding:14px 32px; border-radius:50px; font-family:var(--ff); font-size:12px; font-weight:500; letter-spacing:1.5px; text-transform:uppercase; text-decoration:none; cursor:pointer; transition:all .3s; }
.btn-outline:hover { border-color:var(--gold); color:var(--gold); }
.hero-stats { display:flex; gap:40px; margin-top:44px; animation:fadeUp .8s ease .6s both; }
.stat-num { font-family:var(--fd); font-size:32px; font-weight:600; color:var(--gold); display:block; }
.stat-lbl { font-size:11px; font-weight:400; color:var(--mgray); letter-spacing:1px; text-transform:uppercase; margin-top:2px; display:block; }

.hero-mosaic { flex:1; display:grid; grid-template-columns:1fr 1fr; gap:14px; max-width:520px; animation:fadeUp 1s ease .3s both; }
.mosaic-tall { grid-row:1/3; border-radius:var(--rl); overflow:hidden; }
.mosaic-tall img { width:100%; height:100%; object-fit:cover; transition:transform .6s; }
.mosaic-tall:hover img { transform:scale(1.04); }
.mosaic-stack { display:flex; flex-direction:column; gap:14px; }
.mosaic-img { border-radius:var(--rl); overflow:hidden; flex:1; }
.mosaic-img img { width:100%; height:100%; object-fit:cover; transition:transform .6s; }
.mosaic-img:hover img { transform:scale(1.04); }

/* SECTIONS */
.section { padding:96px 48px; }
.sec-alt { background:var(--bg2); }
.sec-dark { background:var(--black); color:#F5F0EB; }
[data-theme="dark"] .sec-dark { background:#111; }
.sec-solar { background:linear-gradient(135deg,#1a2332,#0f1923); color:#F5F0EB; }
.sec-header { text-align:center; margin-bottom:48px; }
.sec-header-row { display:flex; justify-content:space-between; align-items:flex-end; margin-bottom:48px; flex-wrap:wrap; gap:24px; }
.sec-label { display:inline-flex; align-items:center; gap:8px; font-size:11px; font-weight:600; letter-spacing:3px; text-transform:uppercase; color:var(--gold); margin-bottom:12px; }
.sec-label::before { content:''; width:28px; height:1.5px; background:var(--gold); }
.sec-title { font-family:var(--fd); font-size:clamp(28px,3.8vw,48px); font-weight:300; color:var(--black); line-height:1.15; }
.sec-title em { font-style:italic; color:var(--gold); font-weight:400; }
.sec-sub { font-size:15px; font-weight:300; color:var(--mgray); max-width:500px; line-height:1.7; margin-top:12px; }
.sec-header .sec-sub { margin:12px auto 0; }

/* SERVICES */
.services-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:20px; }
.srv-card { background:var(--bg); border-radius:var(--rl); padding:36px 28px; border:1px solid transparent; transition:all .4s; cursor:pointer; }
.srv-card:hover { transform:translateY(-6px); border-color:rgba(196,162,101,0.25); box-shadow:0 16px 48px rgba(0,0,0,0.05); }
[data-theme="dark"] .srv-card { background:var(--bg); }
.srv-icon { width:52px; height:52px; background:rgba(196,162,101,0.08); border-radius:14px; display:flex; align-items:center; justify-content:center; font-size:22px; margin-bottom:20px; }
.srv-card h3 { font-family:var(--fd); font-size:22px; font-weight:500; color:var(--black); margin-bottom:10px; }
.srv-card p { font-size:13px; line-height:1.65; color:var(--mgray); font-weight:300; }
.srv-link { display:inline-flex; align-items:center; gap:6px; margin-top:20px; font-size:11px; font-weight:600; letter-spacing:1.5px; text-transform:uppercase; color:var(--gold); text-decoration:none; transition:gap .3s; }
.srv-link:hover { gap:12px; }

/* GALLERY */
.gallery-grid { display:grid; grid-template-columns:repeat(4,1fr); grid-auto-rows:240px; gap:14px; }
.gal-item { border-radius:var(--rl); overflow:hidden; position:relative; cursor:pointer; }
.gal-big { grid-column:1/3; grid-row:1/3; }
.gal-item img { width:100%; height:100%; object-fit:cover; transition:transform .6s; }
.gal-item:hover img { transform:scale(1.05); }
.gal-overlay { position:absolute; inset:0; background:linear-gradient(to top,rgba(0,0,0,0.5),transparent 60%); opacity:0; transition:opacity .3s; display:flex; align-items:flex-end; padding:20px; }
.gal-overlay span { color:#fff; font-size:13px; font-weight:500; letter-spacing:1px; }
.gal-item:hover .gal-overlay { opacity:1; }

/* CATEGORIES */
.cat-grid { display:grid; grid-template-columns:repeat(6,1fr); gap:16px; }
.cat-card { text-align:center; padding:28px 14px; border-radius:var(--rl); background:var(--bg); border:1px solid transparent; transition:all .3s; cursor:pointer; }
.cat-card:hover { transform:translateY(-4px); border-color:rgba(196,162,101,0.25); box-shadow:0 10px 36px rgba(0,0,0,0.04); }
[data-theme="dark"] .cat-card { background:var(--bg); }
.cat-icon { width:56px; height:56px; margin:0 auto 12px; background:rgba(196,162,101,0.06); border-radius:16px; display:flex; align-items:center; justify-content:center; font-size:24px; }
.cat-card h4 { font-family:var(--fd); font-size:18px; font-weight:500; color:var(--black); }
.cat-card p { font-size:11px; color:var(--mgray); margin-top:4px; font-weight:300; }

/* TRANSFORM */
.transform-grid { display:grid; grid-template-columns:1fr 1fr; gap:56px; align-items:start; }
.transform-form { display:flex; flex-direction:column; gap:14px; }
.fg { display:flex; flex-direction:column; gap:5px; }
.fg label { font-size:11px; font-weight:600; letter-spacing:1.5px; text-transform:uppercase; color:var(--gold); }
.sec-dark .fg input, .sec-dark .fg textarea, .sec-dark .fg select, .sec-solar .fg input, .sec-solar .fg select { background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); border-radius:12px; padding:13px 16px; color:#F5F0EB; font-family:var(--ff); font-size:14px; transition:border-color .3s; }
.sec-dark .fg input:focus, .sec-dark .fg textarea:focus, .sec-solar .fg input:focus { outline:none; border-color:var(--gold); }
.fg input, .fg textarea, .fg select { background:var(--bg); border:1px solid var(--gray); border-radius:12px; padding:13px 16px; color:var(--dark); font-family:var(--ff); font-size:14px; transition:border-color .3s; }
.fg input:focus, .fg textarea:focus { outline:none; border-color:var(--gold); }
.fg textarea { resize:vertical; min-height:80px; }
.form-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
.upload-zone { border:2px dashed rgba(196,162,101,0.25); border-radius:var(--r); padding:32px; text-align:center; cursor:pointer; transition:all .3s; }
.upload-zone:hover { border-color:var(--gold); background:rgba(196,162,101,0.03); }
.upload-zone p { font-size:13px; color:var(--mgray); }
.upload-zone span { font-size:11px; color:var(--mgray); opacity:.5; }
.file-previews { display:flex; gap:10px; flex-wrap:wrap; }
.file-preview { width:72px; height:72px; border-radius:12px; overflow:hidden; position:relative; }
.file-preview img { width:100%; height:100%; object-fit:cover; }
.file-preview button { position:absolute; top:2px; right:2px; width:20px; height:20px; border-radius:50%; background:rgba(0,0,0,0.6); color:#fff; border:none; cursor:pointer; font-size:12px; display:flex; align-items:center; justify-content:center; }
.success-msg { text-align:center; padding:48px; }
.success-msg h3 { font-family:var(--fd); font-size:28px; margin-bottom:8px; }
.success-msg p { color:var(--mgray); }

.transform-visual { display:flex; flex-direction:column; gap:20px; align-items:center; }
.tv-img { border-radius:var(--rl); overflow:hidden; width:100%; }
.tv-img img { width:100%; height:280px; object-fit:cover; }
.tv-label { text-align:center; }
.tv-label h3 { font-family:var(--fd); font-size:24px; color:#F5F0EB; }
.tv-label p { font-size:13px; color:var(--mgray); }

/* SOLAR */
.solar-grid { display:grid; grid-template-columns:1fr 1fr; gap:56px; align-items:start; }
.solar-info { display:flex; flex-direction:column; gap:20px; }
.solar-info p { font-size:15px; line-height:1.7; color:rgba(245,240,235,0.65); font-weight:300; }
.solar-features { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
.sf-card { background:rgba(255,255,255,0.04); border-radius:var(--r); padding:18px; border:1px solid rgba(196,162,101,0.12); }
.sf-icon { font-size:22px; margin-bottom:6px; display:block; }
.sf-card h4 { font-family:var(--fd); font-size:16px; font-weight:500; margin-bottom:2px; }
.sf-card p { font-size:11px; color:rgba(245,240,235,0.4); }
.calc-card { background:rgba(255,255,255,0.03); border:1px solid rgba(196,162,101,0.18); border-radius:var(--rl); padding:36px; }
.calc-card h3 { font-family:var(--fd); font-size:24px; margin-bottom:6px; }
.calc-sub { font-size:12px; color:rgba(245,240,235,0.4); margin-bottom:28px; }
.calc-results { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:20px; padding-top:20px; border-top:1px solid rgba(255,255,255,0.06); }
.cr { background:rgba(196,162,101,0.06); border-radius:12px; padding:14px; text-align:center; }
.cr-val { font-family:var(--fd); font-size:22px; font-weight:600; color:var(--gold); display:block; }
.cr-lbl { font-size:9px; letter-spacing:1px; text-transform:uppercase; color:rgba(245,240,235,0.4); margin-top:3px; display:block; }

/* BLOG */
.blog-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:20px; }
.blog-card { border-radius:var(--rl); overflow:hidden; background:var(--bg); border:1px solid transparent; transition:all .3s; cursor:pointer; }
.blog-card:hover { transform:translateY(-4px); border-color:rgba(196,162,101,0.2); box-shadow:0 12px 36px rgba(0,0,0,0.04); }
[data-theme="dark"] .blog-card { background:var(--bg); }
.blog-img { height:200px; overflow:hidden; }
.blog-img img { width:100%; height:100%; object-fit:cover; transition:transform .5s; }
.blog-card:hover .blog-img img { transform:scale(1.06); }
.blog-body { padding:24px; }
.blog-cat { font-size:10px; font-weight:600; letter-spacing:2px; text-transform:uppercase; color:var(--gold); }
.blog-body h3 { font-family:var(--fd); font-size:20px; font-weight:500; color:var(--black); margin:8px 0; }
.blog-body p { font-size:13px; color:var(--mgray); line-height:1.6; font-weight:300; }

/* FAQ */
.faq-list { max-width:680px; margin:0 auto; display:flex; flex-direction:column; gap:8px; }
.faq-item { background:var(--bg2); border-radius:14px; padding:20px 24px; cursor:pointer; transition:all .3s; border:1px solid transparent; }
.faq-item:hover, .faq-item.open { border-color:rgba(196,162,101,0.2); }
[data-theme="dark"] .faq-item { background:var(--bg2); }
.faq-q { display:flex; justify-content:space-between; align-items:center; font-weight:500; font-size:15px; color:var(--black); }
.faq-arrow { color:var(--gold); font-size:20px; font-weight:300; }
.faq-a { margin-top:12px; font-size:14px; color:var(--mgray); line-height:1.6; font-weight:300; }

/* CONTACT */
.contact-grid { display:grid; grid-template-columns:1.2fr 1fr; gap:48px; }
.contact-form { display:flex; flex-direction:column; gap:14px; }
.contact-info { display:flex; flex-direction:column; gap:20px; }
.contact-info h3 { font-family:var(--fd); font-size:24px; font-weight:500; color:var(--black); }
.ci-item { display:flex; gap:14px; align-items:flex-start; font-size:14px; color:var(--dark); }
.ci-item span { font-size:20px; }
.ci-item strong { font-weight:600; }
.contact-map { border-radius:var(--r); overflow:hidden; margin-top:8px; }

/* FOOTER */
.footer { background:#111; color:rgba(245,240,235,0.65); padding:72px 48px 28px; }
[data-theme="dark"] .footer { background:#0a0908; }
.footer-grid { display:grid; grid-template-columns:2fr 1fr 1fr 1fr; gap:40px; margin-bottom:48px; }
.footer-logo { height:32px; margin-bottom:14px; filter:brightness(10); }
.footer-brand p { font-size:13px; line-height:1.7; font-weight:300; max-width:300px; }
.footer-col h4 { font-family:var(--fd); font-size:16px; font-weight:500; color:#F5F0EB; margin-bottom:16px; }
.footer-col a { display:block; font-size:12px; color:rgba(245,240,235,0.45); text-decoration:none; margin-bottom:8px; transition:color .3s; }
.footer-col a:hover { color:var(--gold); }
.footer-bottom { display:flex; justify-content:space-between; align-items:center; padding-top:24px; border-top:1px solid rgba(255,255,255,0.06); font-size:11px; }
.footer-social { display:flex; gap:12px; }
.footer-social a { width:36px; height:36px; border-radius:50%; border:1px solid rgba(255,255,255,0.1); display:flex; align-items:center; justify-content:center; color:rgba(245,240,235,0.45); text-decoration:none; transition:all .3s; font-size:13px; font-weight:600; }
.footer-social a:hover { border-color:var(--gold); color:var(--gold); }

/* WHATSAPP */
.wa-float { position:fixed; bottom:24px; right:24px; width:56px; height:56px; background:#25D366; border-radius:50%; display:flex; align-items:center; justify-content:center; color:#fff; font-size:26px; text-decoration:none; box-shadow:0 4px 20px rgba(37,211,102,0.35); z-index:999; transition:transform .3s; animation:waPulse 2s infinite; }
.wa-float:hover { transform:scale(1.1); }
@keyframes waPulse { 0%,100%{box-shadow:0 4px 20px rgba(37,211,102,0.35)} 50%{box-shadow:0 4px 28px rgba(37,211,102,0.55)} }
@keyframes fadeUp { from{opacity:0;transform:translateY(28px)} to{opacity:1;transform:translateY(0)} }

/* ADMIN */
.admin-login-wrap { min-height:100vh; display:flex; align-items:center; justify-content:center; background:var(--bg); padding:20px; }
.admin-login-card { background:var(--bg2); border-radius:var(--rl); padding:48px 40px; max-width:420px; width:100%; border:1px solid var(--gray); }
.admin-login-card h2 { font-family:var(--fd); font-size:28px; color:var(--black); margin-bottom:4px; }
.login-error { background:rgba(220,38,38,0.1); color:#dc2626; padding:10px 16px; border-radius:10px; font-size:13px; margin-bottom:16px; }

.admin-wrap { display:flex; min-height:100vh; background:var(--bg); }
.admin-sidebar { width:260px; background:var(--black); color:#F5F0EB; padding:24px 16px; display:flex; flex-direction:column; position:fixed; top:0; left:0; bottom:0; }
[data-theme="dark"] .admin-sidebar { background:#111; }
.admin-brand { display:flex; align-items:center; gap:10px; margin-bottom:32px; padding:0 8px; font-weight:600; font-size:14px; letter-spacing:1px; }
.admin-nav { display:flex; flex-direction:column; gap:4px; flex:1; }
.admin-tab { display:flex; align-items:center; gap:10px; padding:10px 14px; border:none; background:transparent; color:rgba(245,240,235,0.5); font-family:var(--ff); font-size:13px; font-weight:400; cursor:pointer; border-radius:10px; transition:all .2s; text-align:left; }
.admin-tab:hover { background:rgba(255,255,255,0.05); color:#F5F0EB; }
.admin-tab.active { background:rgba(196,162,101,0.15); color:var(--gold); font-weight:500; }
.admin-user { display:flex; align-items:center; gap:10px; padding:12px 8px; border-top:1px solid rgba(255,255,255,0.06); margin-top:16px; font-size:12px; }
.admin-avatar { width:32px; height:32px; background:var(--gold); border-radius:50%; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:600; font-size:14px; }
.admin-logout { margin-top:12px; padding:8px; background:transparent; border:1px solid rgba(255,255,255,0.1); border-radius:8px; color:rgba(245,240,235,0.5); font-family:var(--ff); font-size:12px; cursor:pointer; transition:all .2s; }
.admin-logout:hover { border-color:var(--gold); color:var(--gold); }

.admin-main { flex:1; margin-left:260px; padding:24px 36px; }
.admin-topbar { display:flex; justify-content:space-between; align-items:center; margin-bottom:32px; }
.admin-topbar h1 { font-family:var(--fd); font-size:28px; font-weight:400; color:var(--black); }
.admin-date { font-size:12px; color:var(--mgray); }
.admin-content { }

.dash-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:16px; }
.dash-card { background:var(--bg2); border-radius:var(--r); padding:28px; border:1px solid var(--gray); transition:all .3s; }
.dash-card:hover { border-color:rgba(196,162,101,0.3); }
.dc-icon { font-size:24px; margin-bottom:12px; }
.dc-num { font-family:var(--fd); font-size:32px; font-weight:600; color:var(--gold); }
.dc-label { font-size:12px; color:var(--mgray); margin-top:4px; letter-spacing:.5px; }
.admin-empty { text-align:center; padding:48px; color:var(--mgray); font-size:14px; background:var(--bg2); border-radius:var(--r); }

.admin-table-wrap { overflow-x:auto; border-radius:var(--r); border:1px solid var(--gray); }
.admin-table { width:100%; border-collapse:collapse; font-size:13px; }
.admin-table th { background:var(--bg2); padding:12px 16px; text-align:left; font-weight:600; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:var(--mgray); border-bottom:1px solid var(--gray); }
.admin-table td { padding:12px 16px; border-bottom:1px solid var(--gray); color:var(--dark); }

.admin-form-card { background:var(--bg2); border-radius:var(--r); padding:28px; margin-bottom:24px; border:1px solid var(--gray); }
.admin-cards { display:grid; grid-template-columns:repeat(auto-fill,minmax(300px,1fr)); gap:14px; }
.admin-item-card { background:var(--bg2); border-radius:14px; padding:20px; border:1px solid var(--gray); }
.aic-header { display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; }
.aic-header strong { font-size:15px; color:var(--black); }
.aic-btn { background:transparent; border:1px solid var(--gray); border-radius:8px; width:30px; height:30px; cursor:pointer; display:flex; align-items:center; justify-content:center; font-size:14px; transition:all .2s; }
.aic-btn:hover { border-color:var(--gold); }
.aic-detail { font-size:12px; color:var(--mgray); margin-top:4px; }
.aic-detail small { font-weight:600; color:var(--dark); }

.admin-solar-config { max-width:600px; }

/* RESPONSIVE */
@media(max-width:1100px) {
  .services-grid { grid-template-columns:repeat(2,1fr); }
  .gallery-grid { grid-template-columns:repeat(2,1fr); grid-auto-rows:200px; }
  .gal-big { grid-column:1/3; }
  .cat-grid { grid-template-columns:repeat(3,1fr); }
  .blog-grid { grid-template-columns:1fr; }
  .solar-grid { grid-template-columns:1fr; }
  .transform-grid { grid-template-columns:1fr; }
  .contact-grid { grid-template-columns:1fr; }
  .footer-grid { grid-template-columns:1fr 1fr; }
  .dash-grid { grid-template-columns:repeat(2,1fr); }
}
@media(max-width:768px) {
  .navbar { padding:14px 20px; }
  .nav-links { display:none; }
  .hamburger { display:flex; }
  .nav-links.open { display:flex; flex-direction:column; position:fixed; top:70px; left:0; right:0; background:var(--bg); padding:20px; gap:14px; border-bottom:1px solid var(--gray); z-index:999; box-shadow:0 8px 24px rgba(0,0,0,0.1); }
  .nav-cta { display:none; }
  .hero { flex-direction:column; padding:100px 20px 48px; gap:32px; }
  .hero-content { max-width:100%; }
  .hero-mosaic { max-width:100%; max-height:320px; }
  .hero-stats { gap:20px; }
  .stat-num { font-size:24px; }
  .section { padding:56px 20px; }
  .services-grid { grid-template-columns:1fr; }
  .gallery-grid { grid-template-columns:1fr; grid-auto-rows:180px; }
  .gal-big { grid-column:auto; }
  .cat-grid { grid-template-columns:repeat(2,1fr); }
  .form-row { grid-template-columns:1fr; }
  .solar-features { grid-template-columns:1fr; }
  .calc-results { grid-template-columns:1fr; }
  .footer-grid { grid-template-columns:1fr; }
  .footer-bottom { flex-direction:column; gap:14px; text-align:center; }
  .admin-sidebar { display:none; }
  .admin-main { margin-left:0; padding:20px; }
  .dash-grid { grid-template-columns:1fr; }
}
`;
